INSERT INTO NOTIFICATION (
    user_id, event_id, notification_type, title, body, created_at
) VALUES (
             #{userId}, #{eventId}, #{notificationType}, #{title}, #{body}, NOW()
         )

mapper.select:
SELECT *
FROM NOTIFICATION
WHERE notification_id = #{notificationId}
  AND user_id = #{userId}
  AND deleted_at IS NULL

SELECT *
FROM NOTIFICATION
WHERE user_id = #{userId}
  AND deleted_at IS NULL
ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE NOTIFICATION
SET deleted_at = NOW()
WHERE notification_id = #{notificationId}
